package tags

import (
    "sort"
    "strings"
)

func Normalize(input []string) []string {
    unique := make(map[string]struct{}, len(input))
    for _, raw := range input {
        tag := strings.ToLower(strings.TrimSpace(raw))
        if tag != "" {
            unique[tag] = struct{}{}
        }
    }
    out := make([]string, 0, len(unique))
    for tag := range unique {
        out = append(out, tag)
    }
    sort.Strings(out)
    return out
}

